#include "codec.h"
#include "structure/decoder.hpp"
#include <cstring>
#include <new>
#include <cstdint>
template<class T>static T get(const uint8_t*p){T x;memcpy(&x,p,sizeof(x));return x;}
struct State{size_t raw,rows,syms,tokens,shift;structure::State* special=nullptr;const uint8_t*index,*bases,*lens,*dict,*stream;};
extern "C" void*lab_open(const uint8_t*a,size_t n){if(n>=4&&get<uint32_t>(a)==structure::magic){auto*t=structure::open(a,n);if(!t)return nullptr;auto*s=new(std::nothrow)State;if(!s){structure::close(t);return nullptr;}s->special=t;return s;}if(n<32||get<uint32_t>(a)!=0x31575046||get<uint32_t>(a+4)!=2)return nullptr;auto*s=new(std::nothrow)State;if(!s)return nullptr;s->raw=get<uint64_t>(a+8);s->rows=get<uint32_t>(a+16);s->syms=get<uint32_t>(a+20);s->tokens=get<uint32_t>(a+24);unsigned group=get<uint32_t>(a+28);if(!group||group>128||(group&(group-1))){delete s;return nullptr;}s->shift=__builtin_ctz(group);size_t directory=4*((s->rows+group)/group)+2*(s->rows+1);size_t d=(32+directory+4*s->syms+15)&~size_t(15);if(s->syms>65536||d>n||16>n-d||2*s->tokens>n-d-16){delete s;return nullptr;}s->bases=a+32;s->index=s->bases+4*((s->rows+group)/group);s->lens=a+32+directory;s->dict=a+d;s->stream=a+n-2*s->tokens;return s;}
static inline size_t range_bounded(State&s,size_t a,size_t b,uint8_t*out,size_t cap){size_t p=0;
 for(;a+4<=b&&p+64<=cap;a+=4){auto t0=get<uint16_t>(s.stream+2*a),t1=get<uint16_t>(s.stream+2*a+2),t2=get<uint16_t>(s.stream+2*a+4),t3=get<uint16_t>(s.stream+2*a+6);auto d0=get<uint32_t>(s.lens+4*t0),d1=get<uint32_t>(s.lens+4*t1),d2=get<uint32_t>(s.lens+4*t2),d3=get<uint32_t>(s.lens+4*t3);memcpy(out+p,s.dict+(d0&0xffffff),16);p+=d0>>24;memcpy(out+p,s.dict+(d1&0xffffff),16);p+=d1>>24;memcpy(out+p,s.dict+(d2&0xffffff),16);p+=d2>>24;memcpy(out+p,s.dict+(d3&0xffffff),16);p+=d3>>24;}
 for(;a<b;a++){auto t=get<uint16_t>(s.stream+2*a);auto d=get<uint32_t>(s.lens+4*t);size_t l=d>>24;if(l>cap-p)return SIZE_MAX;memcpy(out+p,s.dict+(d&0xffffff),cap-p>=16?16:l);p+=l;}return p;}
static inline size_t range(State&s,size_t a,size_t b,uint8_t*out,size_t cap){
 if((b-a)>cap/16)return range_bounded(s,a,b,out,cap);size_t p=0;
 for(;a+4<=b;a+=4){auto t0=get<uint16_t>(s.stream+2*a),t1=get<uint16_t>(s.stream+2*a+2),t2=get<uint16_t>(s.stream+2*a+4),t3=get<uint16_t>(s.stream+2*a+6);auto d0=get<uint32_t>(s.lens+4*t0),d1=get<uint32_t>(s.lens+4*t1),d2=get<uint32_t>(s.lens+4*t2),d3=get<uint32_t>(s.lens+4*t3);memcpy(out+p,s.dict+(d0&0xffffff),16);p+=d0>>24;memcpy(out+p,s.dict+(d1&0xffffff),16);p+=d1>>24;memcpy(out+p,s.dict+(d2&0xffffff),16);p+=d2>>24;memcpy(out+p,s.dict+(d3&0xffffff),16);p+=d3>>24;}
 for(;a<b;a++){auto t=get<uint16_t>(s.stream+2*a);auto d=get<uint32_t>(s.lens+4*t);memcpy(out+p,s.dict+(d&0xffffff),16);p+=d>>24;}return p;}
extern "C" int64_t lab_decode(void*v,uint8_t*out,size_t cap){auto&s=*(State*)v;if(s.special)return structure::decode(s.special,out,cap);if(s.raw>cap)return -1;size_t p=range(s,0,s.tokens,out,cap);return p==s.raw?p:-1;}
extern "C" int64_t lab_rows(void*v,const uint64_t*ids,size_t count,uint8_t*out,size_t cap,uint64_t*offs){auto&s=*(State*)v;if(s.special)return structure::rows(s.special,ids,count,out,cap,offs);
 if(count>=32&&s.raw<=s.rows*32&&ids[0]<s.rows&&count<=s.rows-ids[0]){bool consecutive=true;for(size_t i=1;i<count;i++)if(ids[i]!=ids[0]+i){consecutive=false;break;}if(consecutive){size_t first=ids[0],last=first+count;size_t a=get<uint32_t>(s.bases+4*(first>>s.shift))+get<uint16_t>(s.index+2*first),b=get<uint32_t>(s.bases+4*(last>>s.shift))+get<uint16_t>(s.index+2*last);size_t total=range_bounded(s,a,b,out,cap);if(total==SIZE_MAX)return -1;size_t pos=0,k=0;offs[0]=0;const __m128i lf=_mm_set1_epi8(10);for(;pos+16<=total;pos+=16){unsigned mask=_mm_movemask_epi8(_mm_cmpeq_epi8(_mm_loadu_si128((const __m128i*)(out+pos)),lf));while(mask){if(k>=count)return -1;offs[++k]=pos+__builtin_ctz(mask)+1;mask&=mask-1;}}for(;pos<total;pos++)if(out[pos]==10){if(k>=count)return -1;offs[++k]=pos+1;}if(k<count&&offs[k]<total)offs[++k]=total;return k==count?total:-1;}}
 size_t p=0;offs[0]=0;for(size_t i=0;i<count;i++){if(ids[i]>=s.rows)return -1;size_t id=ids[i];size_t a=get<uint32_t>(s.bases+4*(id>>s.shift))+get<uint16_t>(s.index+2*id),b=get<uint32_t>(s.bases+4*((id+1)>>s.shift))+get<uint16_t>(s.index+2*(id+1));size_t k=range(s,a,b,out+p,cap-p);if(k==SIZE_MAX)return -1;p+=k;offs[i+1]=p;}return p;}
extern "C" void lab_close(void*v){auto*s=(State*)v;if(s){structure::close(s->special);delete s;}}
